-- 线性表模块：已知前驱时的安全指针改接。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '链表结点的插入与删除','在 p 后插入 s 先令 s.next=p.next 再令 p.next=s；删除 p 的后继 q 时令 p.next=q.next，避免断链。',course.id,parent.id,'cs408-linked-list-insert-delete','AISTU',1,'REVIEWED',5,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-linked-list-insert-delete' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-linked-list-insert-delete',1,'REVIEWED','链表结点的插入与删除',JSON_OBJECT('summary','在结点 p 后插入 s 时，先让 s.next 指向原后继，再把 p.next 改为 s；删除 p 的后继 q 时先让 p.next 指向 q.next，再回收 q。指针赋值顺序必须保留仍需访问的链路。','steps',JSON_ARRAY('插入先保存原后继到新结点 next','再将前驱 p 的 next 改指向新结点','删除时由已知前驱绕过目标后继','若删除给定结点本身，单链表仍要先定位前驱'),'prerequisite',JSON_OBJECT('contentKey','cs408-singly-linked-list','title','单链表的结点与表示','description','先掌握 next 指针如何定义逻辑顺序。')),JSON_OBJECT('id','linked-list-insert-delete-v1','prompt','在 p 后插入新结点 s 时，第一步应执行哪条指针赋值？','options',JSON_ARRAY(JSON_OBJECT('id','CONNECT_SUCCESSOR','text','s.next = p.next，先保留原后继链路'),JSON_OBJECT('id','SWITCH_PREDECESSOR','text','p.next = s，先切换前驱入口')),'correctOptionId','CONNECT_SUCCESSOR','correctExplanation','正确：先让新结点接住原后继，才能在修改 p.next 后保持链路完整。','incorrectExplanation','不正确：若先修改 p.next，且未保存原后继，原后继入口可能丢失。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-linked-list-insert-delete' AND existing.content_version=1 WHERE point.content_key='cs408-linked-list-insert-delete' AND existing.id IS NULL;
